mapper.insert:
insert into crm_ai_playbook_run (
    tenant_id, playbook_id, playbook_version, subject_type, subject_id, trigger_source,
    status, context_json, final_output, error_message, started_at, finished_at, create_by, create_time
) values (
    #{tenantId}, #{playbookId}, #{playbookVersion}, #{subjectType}, #{subjectId}, #{triggerSource},
    #{status}, #{contextJson}, #{finalOutput}, #{errorMessage}, #{startedAt}, #{finishedAt}, #{createBy}, #{createTime}
)

mapper.select:
select id, tenant_id, playbook_id, playbook_version, subject_type, subject_id, trigger_source,
       status, context_json, final_output, error_message, started_at, finished_at, create_by, create_time
from crm_ai_playbook_run
where tenant_id = #{tenantId}

    and subject_type = #{subjectType}


    and subject_id = #{subjectId}


    and playbook_id = #{playbookId}

order by id desc
